import json, re, gzip, base64, urllib.request
cfg = open('config.js').read(); url = re.search(r'https://script\.google\.com/[^"\']+', cfg).group(0)
def call(fn, *args):
  req = urllib.request.Request(url, data=json.dumps({'fn': fn, 'args': list(args)}).encode(), headers={'Content-Type': 'text/plain', 'User-Agent': 'diag'})
  return json.loads(urllib.request.urlopen(req, timeout=90).read().decode())
out = []
d = call('getWeeks')['res']
f = d.get('2026-10-12') or {}
if f.get('title', '').startswith('Touring') and '2026-10-19' not in d:
  nf = dict(f); nf['monday'] = '2026-10-19'
  for s in nf.get('sentences', []): s.pop('audio', None); s.pop('alt', None)
  nf.pop('longAudio', None)
  out.append('move forest -> 10-19: ' + json.dumps(call('saveWeek', '2026-10-19', nf, False))[:120])
rice = json.loads(gzip.decompress(base64.b64decode('')).decode())
d = call('getWeeks')['res']
if '2026-10-19' in d and d['2026-10-19'].get('title', '').startswith('Touring'):
  out.append('restore rice -> 10-12: ' + json.dumps(call('saveWeek', '2026-10-12', rice, False))[:120])
d = call('getWeeks')['res']
out += [f"{k} | {d[k].get('title')} | {len(d[k].get('sentences', []))}" for k in sorted(d)]
open('diag/qa_result.txt', 'w').write('\n'.join(out) + '\n'); print('\n'.join(out))
